import os, glob, re

def load_grids():
    d = os.path.normpath(os.environ['RLM_SESSION_DIR'])
    session_file = d + '/../../sessions/' + os.path.basename(d) + '.jsonl'
    with open(session_file, 'r') as f:
        content = f.read().replace('\\n', '\n')

    G = {}
    for msg in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', content):
        k, h, w = int(msg.group(1)), int(msg.group(2)), int(msg.group(3))
        grid_part = content[msg.end():].split('\n')[:h]
        if len(grid_part) == h and all(len(row) == w and all(x.isdigit() for x in row) for row in grid_part):
            G[k] = [[int(x) for x in row] for row in grid_part]
    return G

